mapper.select:
select a.INDENTIFY_MARK, a.ORG_INDENTIFY_MARK, a.REGIST_BANK_CODE, a.IS_BELONG_BANK, a.THE_BANK_NAME, a.THE_BANK_CODE, a.HOLDER_MARK, a.HOLDER_REGION, a.HOLDER_TYPE, a.PERSONAL_IDENTIFY_TYPE, a.INSTITUTION_IDENTIFY_TYPE, a.OTHER_IDENTIFY_NAME, a.IDENTIFY_NUMBER, a.SPV_CAP_ACC_BANK, a.OTHER_CAP_ACC_BANK, a.SPV_REGIST_CODE, a.HOLDER_DATE, a.HOLDER_NAME, a.HOLDER_SEX, a.HOLDER_RISK_PREFER, a.HOLDER_CELLPHONE, a.HOLDER_TELEPHONE, a.IS_SUBMIT, a.HOLDER_EMAIL, a.REMARK, a.STATUS, a.WORKFLOW_ID, a.DEPT_CODE, a.UPDATE_USER, a.UPDATE_TIME, a.CREATE_USER, a.CREATE_TIME,a.DATA_DATE, a.DATA_SOURCE, a.ORG_CODE, a.AGENT, a.CREATE_DEPT, a.INTERF_CHECK_RESULT,a.OPERATE_STATUS,a.MERGER_INDENTIFY_MARK, IM.IMARK,sub.INDENTIFY_MARK isOrNoSubmit, a.HOLDER_CLASSIFY,a.FUND_ACC_PLACE from CHB_EQU_HOLD_CHECK a left join chb_equ_sub sub on sub.INDENTIFY_MARK=a.MERGER_INDENTIFY_MARK and sub.SUBMIT_STATUS in ('02','03') left join ( SELECT INDENTIFY_MARK IMARK, HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER, rank() over( partition by HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER order by INDENTIFY_MARK desc) ineerrank FROM CHB_EQU_HOLD_CHECK ) IM ON a.HOLDER_NAME=IM.HOLDER_NAME AND nvl(a.PERSONAL_IDENTIFY_TYPE,a.INSTITUTION_IDENTIFY_TYPE)=nvl(IM.PERSONAL_IDENTIFY_TYPE,IM.INSTITUTION_IDENTIFY_TYPE) and nvl(a.OTHER_IDENTIFY_NAME,1)=nvl(IM.OTHER_IDENTIFY_NAME,1) and a.IDENTIFY_NUMBER=IM.IDENTIFY_NUMBER AND IM.INEERRANK = 1 where 1=1
and a.MERGER_INDENTIFY_MARK like concat(concat('%', #{mergerIndentifyMark,jdbcType=VARCHAR}),'%')
and a.IDENTIFY_NUMBER like concat(concat('%', #{identifyNumber,jdbcType=VARCHAR}),'%')
and a.HOLDER_NAME like concat(concat('%', #{holderName,jdbcType=VARCHAR}),'%')
#{items,jdbcType=VARCHAR}
and to_char(a.DATA_DATE,'yyyy-mm-dd') >= #{dataTimeStart,jdbcType=VARCHAR}
and to_char(a.DATA_DATE,'yyyy-mm-dd') <= #{dataTimeEnd,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
order by DECODE(a.INSTITUTION_IDENTIFY_TYPE,NULL,'A','B') desc,IMARK desc,a.INDENTIFY_MARK desc

select from CHB_EQU_HOLD_CHECK where 1=1 AND OPERATE_STATUS = '01'
AND REGIST_BANK_CODE ||'_'||IDENTIFY_NUMBER ||'_'||HOLDER_NAME ||'_'||PERSONAL_IDENTIFY_TYPE ||'_'||INSTITUTION_IDENTIFY_TYPE ||'_'||OTHER_IDENTIFY_NAME IN
#{key,jdbcType=VARCHAR}

select 
	from CHB_EQU_HOLD_CHECK
    where 1=1

      and INDENTIFY_MARK=#{indentifyMark,jdbcType=VARCHAR}


      and ORG_INDENTIFY_MARK=#{orgIndentifyMark,jdbcType=VARCHAR}


      and REGIST_BANK_CODE=#{registBankCode,jdbcType=VARCHAR}


      and IS_BELONG_BANK=#{isBelongBank,jdbcType=CHAR}


      and THE_BANK_NAME=#{theBankName,jdbcType=VARCHAR}


      and THE_BANK_CODE=#{theBankCode,jdbcType=VARCHAR}


      and HOLDER_MARK=#{holderMark,jdbcType=CHAR}


      and HOLDER_REGION=#{holderRegion,jdbcType=VARCHAR}


      and HOLDER_TYPE=#{holderType,jdbcType=CHAR}


      and PERSONAL_IDENTIFY_TYPE=#{personalIdentifyType,jdbcType=CHAR}


      and INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


      and OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}


      and IDENTIFY_NUMBER=#{identifyNumber,jdbcType=VARCHAR}


      and SPV_CAP_ACC_BANK=#{spvCapAccBank,jdbcType=VARCHAR}


      and OTHER_CAP_ACC_BANK=#{otherCapAccBank,jdbcType=VARCHAR}


      and SPV_REGIST_CODE=#{spvRegistCode,jdbcType=VARCHAR}


      and HOLDER_DATE=#{holderDate,jdbcType=TIMESTAMP}


      and HOLDER_NAME=#{holderName,jdbcType=VARCHAR}


      and HOLDER_SEX=#{holderSex,jdbcType=CHAR}


      and HOLDER_RISK_PREFER=#{holderRiskPrefer,jdbcType=VARCHAR}


      and HOLDER_CELLPHONE=#{holderCellphone,jdbcType=VARCHAR}


      and HOLDER_TELEPHONE=#{holderTelephone,jdbcType=VARCHAR}


      and IS_SUBMIT=#{isSubmit,jdbcType=CHAR}


      and HOLDER_EMAIL=#{holderEmail,jdbcType=VARCHAR}


      and STATUS=#{status,jdbcType=VARCHAR}


      and AGENT=#{agent,jdbcType=VARCHAR}


      and INTERF_CHECK_RESULT=#{interfCheckResult,jdbcType=VARCHAR}

select a.INDENTIFY_MARK, a.ORG_INDENTIFY_MARK, a.REGIST_BANK_CODE, a.IS_BELONG_BANK, a.THE_BANK_NAME, a.THE_BANK_CODE, a.HOLDER_MARK, a.HOLDER_REGION, a.HOLDER_TYPE, a.PERSONAL_IDENTIFY_TYPE, a.INSTITUTION_IDENTIFY_TYPE, a.OTHER_IDENTIFY_NAME, a.IDENTIFY_NUMBER, a.SPV_CAP_ACC_BANK, a.OTHER_CAP_ACC_BANK, a.SPV_REGIST_CODE, a.HOLDER_DATE, a.HOLDER_NAME, a.HOLDER_SEX, a.HOLDER_RISK_PREFER, a.HOLDER_CELLPHONE, a.HOLDER_TELEPHONE, a.IS_SUBMIT, a.HOLDER_EMAIL, a.REMARK, a.STATUS, a.WORKFLOW_ID, a.DEPT_CODE, a.UPDATE_USER, a.UPDATE_TIME, a.CREATE_USER, a.CREATE_TIME,a.DATA_DATE, a.DATA_SOURCE, a.ORG_CODE, a.AGENT, a.CREATE_DEPT, a.INTERF_CHECK_RESULT,a.OPERATE_STATUS,a.MERGER_INDENTIFY_MARK, IM.IMARK,a.HOLDER_CLASSIFY,a.FUND_ACC_PLACE from CHB_EQU_HOLD_CHECK a left join ( SELECT INDENTIFY_MARK IMARK, HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER, rank() over( partition by HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER order by INDENTIFY_MARK desc) ineerrank FROM CHB_EQU_HOLD_CHECK ) IM ON a.HOLDER_NAME=IM.HOLDER_NAME AND nvl(a.PERSONAL_IDENTIFY_TYPE,a.INSTITUTION_IDENTIFY_TYPE)=nvl(IM.PERSONAL_IDENTIFY_TYPE,IM.INSTITUTION_IDENTIFY_TYPE) and nvl(a.OTHER_IDENTIFY_NAME,1)=nvl(IM.OTHER_IDENTIFY_NAME,1) and a.IDENTIFY_NUMBER=IM.IDENTIFY_NUMBER AND IM.INEERRANK = 1 where 1=1
#{items.indentifyMark,jdbcType=VARCHAR}
order by DECODE(a.INSTITUTION_IDENTIFY_TYPE,NULL,'A','B') desc,IMARK desc,a.INDENTIFY_MARK desc

